# using d and known expected output construct; test same-color connector threshold7
from itertools import pairwise

def connect(g, markcolor, bg, linecolor=2, threshold=7):
 r,c=len(g),len(g[0]); o=[row[:] for row in g]
 for i in range(r):
  ps=[j for j,v in enumerate(g[i]) if v==markcolor]
  for a,b in pairwise(ps):
   if b-a<=threshold:
    for j in range(a+1,b):
     if g[i][j]==bg:o[i][j]=linecolor
 for j in range(c):
  ps=[i for i in range(r) if g[i][j]==markcolor]
  for a,b in pairwise(ps):
   if b-a<=threshold:
    for i in range(a+1,b):
     if g[i][j]==bg:o[i][j]=linecolor
 return o
